-- ════════════════════════════════════════════════════════════════════════
-- 2027-05-05-entry-gates-tower-catalogue.generated.sql — THE BURNING TOWER'S RULES AND EACH FLOOR'S BOUND.
-- Generated by tools/gen-tower.mjs from src/data/tower.js and src/core/hunt/tower.js (the stat formula at each floor's Level).
--   Any hand edit FAILS `node tools/gen-tower.mjs --check`.
-- STATUS: STAGED, NOT APPLIED (lane/c-entry-gates, backend-architect, 2026-11-18; Tyler 2026-11-18: "A minimum level to enter the tower").
--   The Coordinator applies (tools/apply-migration.mjs, one file, never inside begin/commit). A FORWARD FILE: it carries
--   2027-04-24-tower-climb-catalogue.generated.sql (lane/c-tower-climb, applied with v0.2.135) whole and adds hr_tower_rules.min_level
--   (TOWER_RULES.minLevel). ORDER: after everything applied with v0.2.137 (2027-05-04-setup-swap-mid-hunt.sql), right before
--   2027-05-05-entry-gates.sql, whose hr_tower_start reads min_level (its §0 refuses without it). No function body, no player row.
--   Before 2027-05-05-entry-gates.sql nothing reads the column, so this file alone moves no behaviour.
-- hr_tower_rules (one row): the Tower's hunt, a room's size, a landing's spacing (a landing is a checkpoint:
--   hr_session_modes.checkpoint_every reads the same number), a floor's and a landing's time, the stair, the highest floor the formula
--   is read at (a floor above it plays its rows), and THE DOOR'S LEVEL (min_level, 10: a climb starts only when the hero and every seat
--   of its party stands at it or over).
-- hr_tower_floors (300 rows, floor 1 to 300): the floor's Level and the most ONE kill on it can pay in Level XP before its session
--   mode's share and its party share (the formula's at that Level, the best-paying role): the settle's XP bound for a climb.
-- Both rewritten whole (no player row points at either). RLS on, no policy, no client grant: only SECURITY DEFINER functions read them.
-- ON THE EA SECURITY LIST with the Tower. REVERSIBLE: drop the min_level column after 2027-05-05-entry-gates.sql's reversal (nothing else reads
--   it); both tables after 2027-04-24-tower-climb.sql's.
-- ════════════════════════════════════════════════════════════════════════
create table if not exists public.hr_tower_rules (
  id               boolean primary key default true check (id),
  hunt_id          text not null unique check (hunt_id ~ '^[a-z0-9_]{1,64}$'),
  room_size        int  not null check (room_size between 2 and 8),
  landing_every    int  not null check (landing_every > 0),
  floor_limit_ms   int  not null check (floor_limit_ms > 0),
  landing_limit_ms int  not null,
  stair_ms         int  not null check (stair_ms > 0),
  floor_top        int  not null check (floor_top > 0),
  constraint hr_tower_rules_landing_time check (landing_limit_ms >= floor_limit_ms),
  constraint hr_tower_rules_top check (floor_top % landing_every = 0)
);
create table if not exists public.hr_tower_floors (
  floor  int    primary key check (floor >= 1),
  level  int    not null check (level >= 1),
  xp_max bigint not null check (xp_max >= 1)
);
do $$
declare t text;
begin
  foreach t in array array['hr_tower_rules', 'hr_tower_floors'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from public, anon, authenticated, service_role', t);
  end loop;
end $$;
comment on table public.hr_tower_rules is '2027-05-05-entry-gates-tower-catalogue.generated.sql: the Burning Tower''s rules (src/data/tower.js TOWER_RULES), one row. Read by hr_tower_start, hr_hunt_admit, hr_hunt_apply_member and the settle''s floor_time proof.';
comment on table public.hr_tower_floors is '2027-05-05-entry-gates-tower-catalogue.generated.sql: each floor''s Level and the most one kill on it pays in Level XP before its mode and party share (src/core/hunt/tower.js towerXpMax). The settle''s XP bound for a climb.';

-- THE DOOR'S LEVEL (lane/c-entry-gates, Tyler 2026-11-18): added to the table 2027-04-24-tower-climb-catalogue.generated.sql made, filled below, then NOT NULL.
alter table public.hr_tower_rules add column if not exists min_level int;

on conflict (id) do update set hunt_id = excluded.hunt_id, room_size = excluded.room_size, landing_every = excluded.landing_every,
  floor_limit_ms = excluded.floor_limit_ms, landing_limit_ms = excluded.landing_limit_ms, stair_ms = excluded.stair_ms,
  floor_top = excluded.floor_top, min_level = excluded.min_level;
alter table public.hr_tower_rules alter column min_level set not null;
alter table public.hr_tower_rules drop constraint if exists hr_tower_rules_min_level;
alter table public.hr_tower_rules add constraint hr_tower_rules_min_level check (min_level between 1 and 999);
comment on column public.hr_tower_rules.min_level is '2027-05-05-entry-gates-tower-catalogue.generated.sql: the Level a hero, and every seat of its party, needs to start a climb (src/data/tower.js TOWER_RULES.minLevel; Tyler 2026-11-18). Read by hr_tower_start and the entry_gates section.';

delete from public.hr_tower_floors;

-- §4 SELF-CHECK: the data's rows, every floor from 1 to the top once and its bound never falling, and no client can read or write a table.
do $$
declare t text; v_role text;
begin
  if (select count(*) from public.hr_tower_rules) <> 1 or (select hunt_id from public.hr_tower_rules) is distinct from 'the_burning_tower'
     or (select floor_top from public.hr_tower_rules) <> 300 or (select stair_ms from public.hr_tower_rules) <> 4000
     or (select min_level from public.hr_tower_rules) is distinct from 10 then
    raise exception 'tower-catalogue §4: hr_tower_rules is not the one row of src/data/tower.js'; end if;
  if (select count(*) from public.hr_tower_floors) <> 300 or (select min(floor) from public.hr_tower_floors) <> 1
     or (select max(floor) from public.hr_tower_floors) <> 300 then
    raise exception 'tower-catalogue §4: hr_tower_floors is not floor 1 to 300, once each'; end if;
  if exists (select 1 from public.hr_tower_floors a join public.hr_tower_floors b on b.floor = a.floor + 1 where b.xp_max < a.xp_max) then
    raise exception 'tower-catalogue §4: a floor''s bound falls under the floor below it'; end if;
  if (select xp_max from public.hr_tower_floors where floor = 300) <> 48399
     or (select xp_max from public.hr_tower_floors where floor = 1) <> 75 then
    raise exception 'tower-catalogue §4: the bounds are not the formula''s'; end if;
  foreach t in array array['hr_tower_rules', 'hr_tower_floors'] loop
    if exists (select 1 from pg_policies where schemaname = 'public' and tablename = t) then
      raise exception 'tower-catalogue §4: a policy opens % to a client', t; end if;
    foreach v_role in array array['anon', 'authenticated'] loop
      if has_table_privilege(v_role, 'public.' || t, 'select') or has_table_privilege(v_role, 'public.' || t, 'insert,update,delete') then
        raise exception 'tower-catalogue §4: % holds a grant on %', v_role, t; end if;
    end loop;
  end loop;
end $$;
